let bible = {}; try { bible = JSON.parse(projF['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
const descOf = (list, name) => String((((Array.isArray(list) ? list : []).find((x) => String((x || {}).name || '') === name)) || {}).visual_description || '');
const urlOf = (r) => {
